const body = $input.first().json.body || $input.first().json || {};
const repoUrl = typeof body.repoUrl === 'string' ? body.repoUrl.trim() : '';
const branch = (body.branch || 'main').trim();

const urlRegex = /^https?:\/\/github\.com\/([a-zA-Z0-9_.-]+)\/([a-zA-Z0-9_.-]+)(\/.*)?$/;
const match = repoUrl.match(urlRegex);
if (!match) {
  return [{ json: { hasError: true, error: { code: 'INVALID_URL', message: 'Please provide a valid public GitHub repository URL.' }, repoUrl } }];
}

const owner = match[1];
const repo = match[2].replace(/\.git$/, '').replace(/\/+$/, '');
return [{ json: { repoUrl, owner, repo, branch, hasError: false } }];

const meta = $input.first().json || {};

if (meta.full_name) {
  return [{ json: { ...meta, validMeta: true } }];
}

const msg = String(meta.message || 'GitHub API request failed.');
let code = 'UPSTREAM_ERROR';
if (msg.includes('Not Found')) code = 'REPO_NOT_FOUND';
else if (msg.toLowerCase().includes('rate limit')) code = 'RATE_LIMITED';

return [{ json: { validMeta: false, error: { code, message: msg } } }];

const items = $input.all();
const meta = items.find(i => i.json.name || i.json.stargazers_count !== undefined)?.json || {};
const treeData = items.find(i => i.json.tree !== undefined)?.json || {};
const repoInfo = $("Parse Repo URL1").first()?.json || {};

const treeList = treeData.tree || [];

// 1. Capped file list for context
const files = treeList
  .filter(item => item.type === 'blob')
  .map(item => item.path)
  .slice(0, 50);

// 2. Extract unique top-level directories and root entry files
const topLevelEntries = [
  ...new Set(
    treeList
      .map(item => item.path.split('/')[0])
      .filter(entry => entry && !entry.startsWith('.'))
  )
].slice(0, 12);

const topDirsStr = topLevelEntries.length > 0 ? topLevelEntries.join(', ') : 'src, docs';

// 3. Build Prompt with Grounded Rules & Non-Echoing Schema
const prompt = `Analyze this GitHub repository based on its metadata and file tree structure.

Repository URL: ${repoInfo.repoUrl || ''}
Name: ${meta.name || repoInfo.repo || 'N/A'}
Description: ${meta.description || "N/A"}
Stars: ${meta.stargazers_count || 0}, Forks: ${meta.forks_count || 0}, Open Issues: ${meta.open_issues_count || 0}
License: ${meta.license?.spdx_id || "None"}

Top-Level Structure / Key Modules:
${topDirsStr}

File Tree Snippet (up to 50 files):
${files.length > 0 ? files.join('\n') : 'File tree unavailable.'}

IMPORTANT RULES:
1. Respond strictly with raw JSON. Do NOT wrap output in markdown backticks (\`\`\`json) and do NOT add intro/outro text.
2. For "archDiagram", generate a valid Mermaid flowchart starting with "graph TD".
3. Ground the architecture nodes in the real Top-Level Structure listed above (${topDirsStr}).
4. STRICT BAN: Do not use generic nodes like "App", "Components", "Store", or "Data" unless they literally appear in the Top-Level Structure.

Format your response STRICTLY as a JSON object with this exact structure:
{
  "summary": {
    "purpose": "Brief high-level description",
    "architecture": "Architecture style summary",
    "quality": "Codebase structure quality assessment",
    "healthScore": 85,
    "healthGrade": "B",
    "strengths": ["string"],
    "recommendations": ["string"]
  },
  "techStack": [
    { "name": "Language/Framework", "category": "language|framework|tool|database", "icon": "emoji", "percentage": 50 }
  ],
  "archDiagram": "<valid mermaid graph TD string using actual repository modules>",
  "stats": {
    "stars": ${meta.stargazers_count || 0},
    "forks": ${meta.forks_count || 0},
    "openIssues": ${meta.open_issues_count || 0},
    "license": "${meta.license?.spdx_id || "None"}",
    "contributors": 1,
    "lastCommit": "${meta.pushed_at || new Date().toISOString()}"
  }
}`;

return [{ json: { prompt, repoInfo, fileTree: files, topDirs: topLevelEntries } }];

// Helper to transform flat array of path strings into nested tree nodes
function buildFileTree(paths) {
  const tree = [];
  paths.forEach(path => {
    const parts = String(path).split('/');
    let current = tree, currentPath = '';
    parts.forEach((part, i) => {
      currentPath = currentPath ? currentPath + '/' + part : part;
      const isLast = i === parts.length - 1;

      let existing = current.find(n => n.name === part);
      if (existing) {
        if (!existing.children && !isLast) {
          existing.children = [];
          existing.type = 'dir';
        }
        if (existing.children) {
          current = existing.children;
        }
      } else {
        if (isLast) {
          current.push({ name: part, path: currentPath, type: 'file', size: 0 });
        } else {
          const newDir = { name: part, path: currentPath, type: 'dir', children: [] };
          current.push(newDir);
          current = newDir.children;
        }
      }
    });
  });
  return tree;
}

// Sanitizes Mermaid syntax and grounds fallbacks in actual repository modules
function sanitizeMermaid(diagramStr, topDirs = []) {
  // Build a clean, dynamic fallback from actual top-level folders
  let fallbackDiagram = "graph TD\n  A[Repository Root] --> B[Source Files]\n  A --> C[Configuration]";
  if (Array.isArray(topDirs) && topDirs.length >= 2) {
    fallbackDiagram = `graph TD\n  Root[Repository Root] --> ${topDirs.slice(0, 4).map((d, idx) => `M${idx}[${d}]`).join('\n  Root --> ')}`;
  }

  if (!diagramStr || typeof diagramStr !== 'string' || diagramStr.includes('<valid mermaid') || diagramStr.includes('A[Client]-->B[Server]')) {
    return fallbackDiagram;
  }

  let cleaned = diagramStr.trim();
  cleaned = cleaned
    .replace(/-->\|([^|]+)\|>/g, "-->|$1|")
    .replace(/---\|([^|]+)\|>/g, "--|$1|")
    .replace(/```mermaid/gi, "")
    .replace(/```/g, "")
    .trim();

  // If the model echoed generic web-app placeholders, override with grounded modules
  const isGeneric = (
    cleaned.includes("A[App]") && cleaned.includes("B[Components]")
  ) || (
    cleaned.includes("A[Client]") && cleaned.includes("B[Server]")
  );

  if (isGeneric) {
    return fallbackDiagram;
  }

  return cleaned.startsWith("graph") ? cleaned : fallbackDiagram;
}

// Node inputs & data sources
const inputItem = $input.first().json || {};
const repoInfo = $("Parse Repo URL1").first()?.json || {};
const apiMeta = $("GitHub Repo Metadata").first()?.json || {};
const treeData = $("GitHub File Tree").first()?.json || {};
const promptNodeData = $("Merge & Build Prompt1").first()?.json || {};

// Attempt to parse AI raw input if present, otherwise fallback cleanly
const aiRaw = inputItem.output || inputItem.text || inputItem.message?.content || (typeof inputItem === 'string' ? inputItem : "");
let parsed = {};
if (aiRaw) {
  if (typeof aiRaw === 'object') {
    parsed = aiRaw;
  } else {
    try {
      let cleaned = String(aiRaw).replace(/```json/gi, "").replace(/```/g, "").trim();
      const startIdx = cleaned.indexOf('{');
      const endIdx = cleaned.lastIndexOf('}');
      if (startIdx !== -1 && endIdx !== -1) {
        cleaned = cleaned.substring(startIdx, endIdx + 1);
      }
      parsed = JSON.parse(cleaned);
    } catch (e) {
      parsed = {};
    }
  }
}

// Calculate tech stack dynamically from GitHub file tree extensions
const treeList = treeData.tree || [];
const extCounts = {};
let totalCodeFiles = 0;

treeList.forEach(item => {
  if (item.type === 'blob') {
    const parts = item.path.split('.');
    if (parts.length > 1) {
      const ext = parts.pop().toLowerCase();
      extCounts[ext] = (extCounts[ext] || 0) + 1;
      totalCodeFiles++;
    }
  }
});

const extMap = {
  py: { name: "Python", category: "language", icon: "🐍" },
  js: { name: "JavaScript", category: "language", icon: "🟨" },
  ts: { name: "TypeScript", category: "language", icon: "⚡" },
  jsx: { name: "React JS", category: "framework", icon: "⚛️" },
  tsx: { name: "React TS", category: "framework", icon: "⚛️" },
  json: { name: "JSON Config", category: "tool", icon: "🔧" },
  yml: { name: "GitHub Actions", category: "tool", icon: "⚙️" },
  yaml: { name: "YAML Config", category: "tool", icon: "⚙️" },
  md: { name: "Documentation", category: "tool", icon: "📝" },
  toml: { name: "TOML Config", category: "tool", icon: "⚙️" },
  sh: { name: "Shell Script", category: "language", icon: "🐚" },
  ps1: { name: "PowerShell", category: "language", icon: "💻" }
};

let calculatedTechStack = Object.entries(extCounts)
  .map(([ext, count]) => {
    const info = extMap[ext] || { name: ext.toUpperCase(), category: "tool", icon: "📁" };
    return {
      name: info.name,
      category: info.category,
      icon: info.icon,
      percentage: Math.round((count / totalCodeFiles) * 100)
    };
  })
  .filter(item => item.percentage >= 3)
  .sort((a, b) => b.percentage - a.percentage)
  .slice(0, 5);

if (calculatedTechStack.length === 0) {
  calculatedTechStack = [
    { name: apiMeta.language || "Source Code", category: "language", icon: "💻", percentage: 100 }
  ];
}

// Extract top-level directories for grounding
const topLevelEntries = promptNodeData.topDirs || [
  ...new Set(
    treeList
      .map(item => item.path.split('/')[0])
      .filter(entry => entry && !entry.startsWith('.'))
  )
].slice(0, 10);

// Dynamic Repository Signal Analysis
const hasTests = treeList.some(i => i.path.toLowerCase().includes('test') || i.path.toLowerCase().includes('spec'));
const hasDocs = treeList.some(i => i.path.toLowerCase().includes('readme') || i.path.toLowerCase().startsWith('docs/'));
const hasCI = treeList.some(i => i.path.startsWith('.github/workflows'));
const hasLicense = Boolean(apiMeta.license?.spdx_id || apiMeta.license?.name);
const openIssuesCount = Number(apiMeta.open_issues_count || 0);

// Dynamic Health Scoring
let healthScore = 65;
if (hasDocs) healthScore += 10;
if (hasTests) healthScore += 10;
if (hasCI) healthScore += 10;
if (hasLicense) healthScore += 5;
if (openIssuesCount > 100) healthScore -= 10;
else if (openIssuesCount > 30) healthScore -= 5;
healthScore = Math.max(40, Math.min(98, healthScore));

let healthGrade = 'C';
if (healthScore >= 85) healthGrade = 'A';
else if (healthScore >= 75) healthGrade = 'B';
else if (healthScore >= 60) healthGrade = 'C';
else healthGrade = 'D';

// Dynamic Strengths
const dynamicStrengths = [];
if (hasDocs) dynamicStrengths.push("Detailed documentation and guides available");
if (hasCI) dynamicStrengths.push("Automated CI/CD integration workflows present");
if (hasTests) dynamicStrengths.push("Dedicated testing infrastructure configured");
if (hasLicense) dynamicStrengths.push(`Clear open-source licensing (${apiMeta.license?.spdx_id || 'Included'})`);
if (dynamicStrengths.length < 2) dynamicStrengths.push("Modular directory structure");

// Dynamic Recommendations
const dynamicRecommendations = [];
if (!hasTests) dynamicRecommendations.push("Add automated unit and integration tests");
if (!hasCI) dynamicRecommendations.push("Configure GitHub Actions for CI/CD checks");
if (!hasDocs) dynamicRecommendations.push("Expand documentation and setup guides");
if (openIssuesCount > 50) dynamicRecommendations.push(`Triage open issue backlog (${openIssuesCount} active issues)`);
if (dynamicRecommendations.length < 2) dynamicRecommendations.push("Maintain dependency version locks");

// Dynamic Architecture Description
let dynamicArch = "Modular directory layout with defined component scopes.";
if (hasCI && hasTests) {
  dynamicArch = "Production-ready structure with CI/CD automation and test suites.";
} else if (hasDocs) {
  dynamicArch = "Well-documented structure with centralized project assets.";
}

// Type Enforcers & Safety Helpers
const safeStr = (val, fallback = "N/A") => (typeof val === 'string' && val.trim() !== '' ? val : fallback);
const safeArr = (val, fallback = []) => (Array.isArray(val) && val.length > 0 ? val : fallback);

// File tree resolution
const rawTree = treeList.length > 0 ? treeList.map(i => i.path) : (promptNodeData.fileTree || parsed.fileTree || []);
const fileTree = Array.isArray(rawTree) && rawTree.length > 0 && typeof rawTree[0] === 'string'
  ? buildFileTree(rawTree)
  : rawTree;

// Base metadata
const owner = safeStr(repoInfo.owner, apiMeta.owner?.login || "dhanvithshetty-in");
const repo = safeStr(repoInfo.repo, apiMeta.name || "gitgrok");
const fullRepoUrl = safeStr(repoInfo.repoUrl, `https://github.com/${owner}/${repo}`);
const currentDateStr = new Date().toISOString();

// Diagram generation grounded in real directories
const rawDiagram = parsed.archDiagram || parsed.architectureDiagram || "";
const cleanDiagram = sanitizeMermaid(rawDiagram, topLevelEntries);

const summaryObj = typeof parsed.summary === 'object' ? parsed.summary : { purpose: parsed.summary };
const repoDescription = apiMeta.description || "GitHub repository codebase.";

// Final unified health metrics
const finalHealthScore = parsed.summary?.healthScore || parsed.summary?.score || parsed.healthScore || healthScore;
const finalHealthGrade = parsed.summary?.healthGrade || parsed.summary?.grade || parsed.healthGrade || healthGrade;

return [{
  json: {
    id: `ana_${Date.now()}`,
    repoUrl: fullRepoUrl,
    full_name: `${owner}/${repo}`,
    name: repo,
    owner: owner,
    branch: safeStr(repoInfo.branch, apiMeta.default_branch || "main"),
    analyzedAt: currentDateStr,

    // Direct root-level keys for UI badges expecting flat properties
    healthScore: finalHealthScore,
    healthGrade: finalHealthGrade,
    health_score: finalHealthScore,
    health_grade: finalHealthGrade,
    score: finalHealthScore,
    grade: finalHealthGrade,

    // Explicit nested object for UI components referencing codeHealth
    codeHealth: {
      score: finalHealthScore,
      grade: finalHealthGrade,
      healthScore: finalHealthScore,
      healthGrade: finalHealthGrade,
      quality: `Repository inspected with health grade ${finalHealthGrade} (${finalHealthScore}%).`
    },

    summary: {
      purpose: safeStr(summaryObj.purpose, repoDescription),
      architecture: safeStr(summaryObj.architecture, dynamicArch),
      quality: `Repository inspected with health grade ${finalHealthGrade} (${finalHealthScore}%).`,
      healthScore: finalHealthScore,
      healthGrade: finalHealthGrade,
      health_score: finalHealthScore,
      health_grade: finalHealthGrade,
      score: finalHealthScore,
      grade: finalHealthGrade,
      strengths: safeArr(summaryObj.strengths, dynamicStrengths),
      recommendations: safeArr(summaryObj.recommendations, dynamicRecommendations)
    },
    techStack: Array.isArray(parsed.techStack) && parsed.techStack.length > 0 ? parsed.techStack : calculatedTechStack,
    fileTree: safeArr(fileTree, []),
    archDiagram: cleanDiagram,
    stats: {
      stars: Number(apiMeta.stargazers_count !== undefined ? apiMeta.stargazers_count : (parsed.stats?.stars || 0)),
      forks: Number(apiMeta.forks_count !== undefined ? apiMeta.forks_count : (parsed.stats?.forks || 0)),
      openIssues: Number(apiMeta.open_issues_count !== undefined ? apiMeta.open_issues_count : (parsed.stats?.openIssues || 0)),
      license: safeStr(apiMeta.license?.spdx_id || apiMeta.license?.name || parsed.stats?.license, "MIT"),
      contributors: Number(parsed.stats?.contributors) || 1,
      lastCommit: safeStr(apiMeta.pushed_at || parsed.stats?.lastCommit, currentDateStr)
    }
  }
}];

const analysis = $("Parse AI Response1").first().json || {};
const saveOut = $input.first().json || {};

let savedId = '';
let persistError = false;
const rows = Array.isArray(saveOut.body) ? saveOut.body : (Array.isArray(saveOut) ? saveOut : []);
if (rows[0] && rows[0].id) savedId = rows[0].id;
else if (saveOut.id) savedId = saveOut.id;
else persistError = true;

return [{ json: { ...analysis, id: savedId || analysis.id, persisted: !persistError, persistError } }];
